(function ($) {
  function initSlider(element, options) {
    var container = element;
    var slides = Array.from(container.children);
    if (!slides.length) return;

    var list = document.createElement("div");
    list.className = "slick-list";
    var track = document.createElement("div");
    track.className = "slick-track";

    slides.forEach(function (slide, index) {
      slide.classList.add("slick-slide");
      slide.dataset.slickIndex = index;
      track.appendChild(slide);
    });

    list.appendChild(track);
    container.appendChild(list);
    container.classList.add("slick-initialized");

    if (options.arrows) {
      var prev = document.createElement("button");
      prev.type = "button";
      prev.className = "slick-arrow slick-prev";
      prev.textContent = "←";
      var next = document.createElement("button");
      next.type = "button";
      next.className = "slick-arrow slick-next";
      next.textContent = "→";
      container.appendChild(prev);
      container.appendChild(next);

      prev.addEventListener("click", function () {
        scrollToIndex(getCurrentIndex() - 1);
      });
      next.addEventListener("click", function () {
        scrollToIndex(getCurrentIndex() + 1);
      });
    }

    list.addEventListener("scroll", function () {
      updateCenterClass();
    });

    function getSlideCenters() {
      return slides.map(function (slide) {
        return slide.offsetLeft + slide.offsetWidth / 2;
      });
    }

    function getCurrentIndex() {
      var centers = getSlideCenters();
      var target = list.scrollLeft + list.clientWidth / 2;
      var closest = 0;
      var min = Infinity;
      centers.forEach(function (center, index) {
        var dist = Math.abs(center - target);
        if (dist < min) {
          min = dist;
          closest = index;
        }
      });
      return closest;
    }

    function scrollToIndex(index) {
      if (index < 0) {
        index = options.infinite ? slides.length - 1 : 0;
      }
      if (index >= slides.length) {
        index = options.infinite ? 0 : slides.length - 1;
      }
      var target = slides[index].offsetLeft + slides[index].offsetWidth / 2 - list.clientWidth / 2;
      list.scrollTo({ left: target, behavior: "smooth" });
      updateCenterClass(index);
    }

    function updateCenterClass(forcedIndex) {
      var current = forcedIndex !== undefined ? forcedIndex : getCurrentIndex();
      slides.forEach(function (slide, index) {
        slide.classList.toggle("slick-center", index === current);
        slide.classList.toggle("slick-active", Math.abs(index - current) <= 1);
      });
    }

    setTimeout(function () {
      updateCenterClass();
    }, 0);

    container._slick = {
      list: list,
      track: track,
      slides: slides,
      destroy: function () {
        if (container.classList.contains("slick-initialized")) {
          container.classList.remove("slick-initialized");
        }
        slides.forEach(function (slide) {
          slide.classList.remove("slick-slide", "slick-center", "slick-active");
          container.appendChild(slide);
        });
        if (options.arrows) {
          container.querySelectorAll(".slick-arrow").forEach(function (arrow) {
            arrow.remove();
          });
        }
        list.remove();
      },
    };
  }

  $.fn.slick = function (options) {
    if (typeof options === "string" && options === "unslick") {
      return this.each(function () {
        if (this._slick) {
          this._slick.destroy();
          this._slick = null;
        }
      });
    }
    var settings = Object.assign(
      {
        centerMode: true,
        variableWidth: true,
        infinite: false,
        arrows: true,
        swipe: true,
      },
      options || {}
    );
    return this.each(function () {
      if (this._slick) {
        this._slick.destroy();
        this._slick = null;
      }
      initSlider(this, settings);
    });
  };
})(window.jQuery);
